149	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
150	        Collection<Owner> owners;
151	        if (lastName != null) {
152	            owners = this.clinicService.findOwnerByLastName(lastName);
153	        } else {
154	            owners = this.clinicService.findAllOwners();
155	        }
156	        if (owners.isEmpty()) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
160	    }
