381	    /**
382	     * Loads the owner with the given id and, when it exists, produces the response through
383	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
384	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
385	     * the not-found response are written in exactly one place rather than copied into each method.
386	     *
387	     * @param ownerId the id of the owner to load
388	     * @param action builds the response for an existing owner
389	     * @param <T> the response body type
390	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
391	     */
392	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
393	        Owner owner = this.clinicService.findOwnerById(ownerId);
394	        if (owner == null) {
395	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
396	        }
397	        return action.apply(owner);
398	    }
399	
400	    /**
401	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
402	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} and
403	     * {@code capacityWarning} flags, the {@code identityKey} and the {@code possibleDuplicate} pair),
404	     * and re-applies the owner's
405	     * {@code membershipLevel} through the controller ({@link #membershipLevel(Owner)}). Both the
406	     * create endpoint and the single-owner read endpoint return their owner through this method, so
407	     * an owner is decorated identically on either path and each derived field is computed in exactly
408	     * one place.
409	     *
410	     * @param owner the persisted owner to represent
411	     * @return the owner DTO with its derived read-only fields populated
412	     */
413	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
414	        owner.setHouseholdSize(householdSize(owner));
415	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
416	        int membershipLevel = membershipLevel(owner);
417	        ownerDto.setMembershipLevel(membershipLevel);
418	        ownerDto.setOwnerSegment(ownerMapper.ownerSegment(owner, membershipLevel));
419	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
420	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
421	        ownerDto.setIdentityKey(identityKey(owner));
422	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
423	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
424	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
425	        return ownerDto;
426	    }
427	
428	    /**
429	     * The {@code membershipLevel} reported for a single owner. Starts from the owner-local derivation
430	     * in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own membership points),
431	     * routed through the controller so the create audit log and the single-owner response agree on one
432	     * value. Unlike the mapper - which sees only the owner - the controller can reach the rest of the
433	     * clinic, so this is the single place a reported membership level is shaped by cross-owner context.
434	     *
435	     * <p>Household ceiling: the reported level is capped at one above the current maximum
436	     * {@linkplain #householdMemberLevel(Owner) level} among the owner's <em>existing</em>
437	     * {@link #householdMembers(Owner) household members} (those sharing its {@code householdId}, other
438	     * than the owner itself). With no existing household member no cap applies and the owner-local level
439	     * is reported unchanged. The cap uses each member's own owner-local level (not their reported,
440	     * capped level), so it depends only on the members' own points and cannot recurse.
441	     *
442	     * @param owner the owner whose reported membership level is wanted
443	     * @return the owner's membership level, capped at one above its household maximum
444	     */
445	    private Integer membershipLevel(Owner owner) {
446	        int ownLevel = ownerMapper.membershipLevel(owner);
447	        java.util.OptionalInt maxHouseholdLevel = householdMembers(owner).stream()
448	            .filter(member -> !java.util.Objects.equals(member.getId(), owner.getId()))
449	            .mapToInt(this::householdMemberLevel)
450	            .max();
451	        if (maxHouseholdLevel.isEmpty()) {
452	            return ownLevel;
453	        }
454	        return Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1);
455	    }
456	
457	    /**
458	     * The owner-local membership level of a household member, used only as an input to the household
459	     * ceiling in {@link #membershipLevel(Owner)}. The member's {@link Owner#getHouseholdSize()
460	     * household size} is set from its household before the level is derived, so the member's household
461	     * factor is accounted for exactly as it is when the member is reported on its own; the level itself
462	     * comes from the owner-local {@link OwnerMapper#membershipLevel(Owner)}.
463	     *
464	     * @param member an existing member of an owner's household
465	     * @return the member's owner-local membership level
466	     */
467	    private int householdMemberLevel(Owner member) {
468	        member.setHouseholdSize(householdSize(member));
469	        return ownerMapper.membershipLevel(member);
470	    }
471	
472	    /**
473	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
474	     * every later step - the required-field check, the persisted value and the response - sees the
475	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
476	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
477	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
478	     * steps that read the address.
479	     *
480	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
481	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
482	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
483	     * are preferred when present: the flat {@code address} returned is composed as the normalized
484	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
485	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
486	     * {@code address} retain its own normalized value.
487	     *
488	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
489	     */
490	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
491	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
492	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
493	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
494	        ownerFieldsDto.setAddressLine1(addressLine1);
495	        ownerFieldsDto.setAddressLine2(addressLine2);
496	        if (addressLine1 != null && !addressLine1.isBlank()) {
497	            String composed = addressLine2 != null && !addressLine2.isBlank()
498	                ? addressLine1 + " " + addressLine2
499	                : addressLine1;
500	            ownerFieldsDto.setAddress(composed);
501	        } else {
502	            ownerFieldsDto.setAddress(flatAddress);
503	        }
504	    }
505	
506	    /**
507	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
508	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
509	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
510	     * blank (e.g. {@code "   "}). The offending field names are reported through an
511	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
512	     * as a 400 response carrying an {@code errors} array of field names.
513	     *
514	     * @param ownerFieldsDto the submitted owner fields
515	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
516	     */
517	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
518	        List<String> blankFields = new ArrayList<>();
519	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
520	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
521	        addRequiredAddress(blankFields, ownerFieldsDto);
522	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
523	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
524	        if (!blankFields.isEmpty()) {
525	            throw new InvalidOwnerFieldsException(blankFields);
526	        }
527	    }
