600	    /**
601	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
602	     * the {@code customerCode}.
603	     */
604	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
605	
606	    /**
607	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
608	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
609	     * its {@code postcode} (falling back to its {@code city}) through the shared
610	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
611	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
612	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
613	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
614	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
615	     * distinct customer codes.
616	     *
617	     * @param owner the owner being created, with its telephone already normalized
618	     * @return the formatted, de-duplicated customer code
619	     */
620	    private String customerCode(Owner owner) {
621	        String region = Region.code(owner.getPostcode(), owner.getCity());
622	        String hash8 = sha256Hasher.hexPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
623	        String base = region + "-" + hash8;
624	        return deduplicateCustomerCode(base);
625	    }
626	
627	    /**
628	     * Ensures the given base {@code customerCode} does not collide with an existing owner's
629	     * {@code customerCode}. When no existing owner carries the base code it is returned unchanged;
630	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code
631	     * held by no existing owner.
632	     *
633	     * @param base the computed base customer code, formatted {@code '<REGION>-<HASH8>'}
634	     * @return the base code, or a {@code '<base>-<n>'} variant that is unique among existing owners
635	     */
636	    private String deduplicateCustomerCode(String base) {
637	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
638	            .map(Owner::getCustomerCode)
639	            .filter(java.util.Objects::nonNull)
640	            .collect(java.util.stream.Collectors.toSet());
641	        if (!existing.contains(base)) {
642	            return base;
643	        }
644	        int n = 2;
645	        while (existing.contains(base + "-" + n)) {
646	            n++;
647	        }
648	        return base + "-" + n;
649	    }
