659	     * @param lastName the last name of the owner being created
660	     * @return the number of existing owners with the same first and last name (case-insensitive)
661	     */
662	    private int namesakeCount(String firstName, String lastName) {
663	        return (int) countOwners(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
664	            && equalsIgnoreCase(owner.getLastName(), lastName));
