768	    /**
769	     * The fixed list of public holidays that are not business days. A registration date that lands
770	     * on one of these is rolled forward by {@link #businessDay(LocalDate)} to the next non-holiday
771	     * business day, exactly as it is rolled forward off a weekend.
772	     */
773	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
774	        LocalDate.of(2026, 1, 1),
775	        LocalDate.of(2026, 1, 26),
776	        LocalDate.of(2026, 4, 25),
777	        LocalDate.of(2026, 12, 25),
778	        LocalDate.of(2026, 12, 28));
