780	    /**
781	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
782	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
783	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
784	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
785	     * value - whether supplied in the request or defaulted to the server date - is stored as the
786	     * next business day, and every value derived from the registration date (such as the membership
787	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
788	     *
789	     * @param date the effective registration date
790	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
791	     */
792	    private LocalDate businessDay(LocalDate date) {
793	        while (isNonBusinessDay(date)) {
794	            date = date.plusDays(1);
795	        }
796	        return date;
797	    }
