799	    /**
800	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
801	     *
802	     * @param date the date to test
803	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
804	     */
805	    private boolean isNonBusinessDay(LocalDate date) {
806	        DayOfWeek dayOfWeek = date.getDayOfWeek();
807	        return dayOfWeek == DayOfWeek.SATURDAY
808	            || dayOfWeek == DayOfWeek.SUNDAY
809	            || PUBLIC_HOLIDAYS.contains(date);
810	    }
