864	    /**
865	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
866	     * The identity key is the SHA-256 hex digest over
867	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
868	     * {@link #identityKey(Owner)}) and is the single duplicate check: it subsumes the former separate
869	     * telephone, email and household duplicate blocks. Because the telephone is part of the key, two
870	     * owners with the same last name and postcode but <em>different</em> telephones have different
871	     * identity keys and are both allowed (the second is surfaced instead as a soft
872	     * {@code possibleDuplicate}, see {@link #possibleDuplicateOf(Owner)}); only an exact full-key match
873	     * is a duplicate. Owners flagged deleted are ignored (see {@link #findExistingOwner(Function, String)}),
874	     * and the email-domain blocklist has already been applied earlier in the create flow. A collision is
875	     * reported through a {@link DuplicateOwnerIdentityException}, which the {@code ExceptionControllerAdvice}
876	     * renders as a 409 Conflict response.
877	     *
878	     * @param owner the fully-populated owner being created (telephone normalized, email set)
879	     * @throws DuplicateOwnerIdentityException if an existing (non-deleted) owner has the same identity key
880	     */
881	    private void rejectDuplicateIdentity(Owner owner) {
882	        String key = identityKey(owner);
883	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
884	        if (duplicate) {
885	            throw new DuplicateOwnerIdentityException(key);
886	        }
887	    }
