889	    /**
890	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
891	     * first existing owner whose {@code identityKey} <em>differs</em> from this owner's yet whose
892	     * {@code lastName} has the same {@linkplain Soundex#encode(String) Soundex code} and whose
893	     * {@code postcode} is equal, or {@code null} when no such owner exists. Because the telephone is
894	     * part of the identity key, an existing owner sharing this owner's last-name sound and postcode but
895	     * carrying a different telephone has a different identity key: it is not a hard duplicate (it passed
896	     * {@link #rejectDuplicateIdentity(Owner)}) and is surfaced here as a soft match instead. An existing
897	     * owner with the <em>same</em> identity key would already have been rejected as a 409 and so is
898	     * excluded by the differing-key condition. A blank {@code postcode} never matches, since two owners
899	     * without a postcode do not share one. The captured id is stored on the new owner and surfaced as
900	     * the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
901	     *
902	     * @param owner the fully-populated owner being created (telephone normalized)
903	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
904	     */
905	    private Integer possibleDuplicateOf(Owner owner) {
906	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
907	            return null;
908	        }
909	        String key = identityKey(owner);
910	        String lastNameSoundex = soundex.encode(owner.getLastName());
911	        return this.clinicService.findAllOwners().stream()
912	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode())
913	                && lastNameSoundex.equals(soundex.encode(existing.getLastName()))
914	                && !key.equals(identityKey(existing)))
915	            .map(Owner::getId)
916	            .filter(java.util.Objects::nonNull)
917	            .findFirst()
918	            .orElse(null);
919	    }
