921	    /**
922	     * Reduces an owner to its derived {@code identityKey}: the full lower-case SHA-256 hex digest (see
923	     * {@link Sha256Hasher#hex(String)}) over {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} -
924	     * the owner's telephone reduced to its canonical E.164 form (see
925	     * {@link TelephoneNormalizer#canonicalize(String)}), the owner's normalized (lower-cased) email or
926	     * the empty string when absent (see {@link EmailNormalizer#normalize(String)}), and the
927	     * {@linkplain Soundex#encode(String) Soundex code} of the owner's last name, joined by {@code '|'}.
928	     * Two owners are duplicates exactly when their whole identity keys are equal. The hashed input never
929	     * contains {@code null} segments, so the create endpoint's single duplicate check compares this one
930	     * value across owners.
931	     *
932	     * @param owner the owner to derive the identity key for
933	     * @return the owner's identity key, a 64-character lower-case hex string
934	     */
935	    private String identityKey(Owner owner) {
936	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
937	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
938	        String email = normalizedEmail == null ? "" : normalizedEmail;
939	        String lastNameSoundex = soundex.encode(owner.getLastName());
940	        return sha256Hasher.hex(telephone + "|" + email + "|" + lastNameSoundex);
941	    }
