943	    /**
944	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
945	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
946	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
947	     * checks reduce both an existing owner and the owner being created to the same canonical key;
948	     * this returns the matched existing owner itself, so a caller can either reject the collision or
949	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
950	     * collision with only a deleted owner is not reported and the create is allowed.
951	     *
952	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
953	     * @param key the canonical key of the owner being created
954	     * @return the first existing owner sharing the key, or empty when none does
955	     */
956	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
957	        return this.clinicService.findAllOwners().stream()
958	            .filter(owner -> !owner.isDeleted())
959	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
960	            .findFirst();
961	    }
