963	    /**
964	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
965	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
966	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
967	     * being created to the same canonical key and reject a match.
968	     *
969	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
970	     * @param key the canonical key of the owner being created
971	     * @return {@code true} if some existing owner shares the key
972	     */
973	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
974	        return findExistingOwner(keyExtractor, key).isPresent();
975	    }
