977	    /**
978	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
979	     * count-based rules - the per-city capacity, the per-day create limit and the derived
980	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
981	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
982	     * place and each rule supplies just its own predicate.
983	     *
984	     * @param predicate the condition an owner must satisfy to be counted
985	     * @return the number of existing owners that satisfy the predicate
986	     */
987	    private long countOwners(Predicate<Owner> predicate) {
988	        return this.clinicService.findAllOwners().stream()
989	            .filter(predicate)
990	            .count();
991	    }
992	
993	    /**
994	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
995	     * shared {@code householdId}.
996	     */
997	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
998	
999	    /**
1000	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
1001	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
1002	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
1003	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
1004	     *
1005	     * @param value the raw field value, or {@code null}
1006	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
1007	     */
1008	    private String canonicalizeHousehold(String value) {
1009	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
1010	    }
1011	
1012	    /**
1013	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
1014	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
1015	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
1016	     * for the last-name normalization), so every owner with the same last name and postcode -
1017	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
1018	     * a postcode have no household basis and are given no household id ({@code null}).
1019	     *
1020	     * @param owner the owner being created
1021	     * @return the shared household identifier, or {@code null} when the owner has no postcode
1022	     */
1023	    /**
1024	     * Counts the owners in the given owner's household: the existing owners that share its
1025	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
1026	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
1027	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
1028	     * household factor of the owner's membership points.
1029	     *
1030	     * @param owner the owner whose household size is being derived
1031	     * @return the number of owners in the owner's household (at least {@code 1})
1032	     */
1033	    private int householdSize(Owner owner) {
1034	        if (owner.getHouseholdId() == null) {
1035	            return 1;
1036	        }
1037	        return householdMembers(owner).size();
1038	    }
1039	
1040	    /**
1041	     * The existing owners that make up the given owner's household: those sharing its
1042	     * {@code householdId} (see {@link #householdId(Owner)}). An owner with no {@code householdId}
1043	     * (e.g. no postcode) belongs to no shared household, so the result is empty. Whether the owner
1044	     * itself appears depends on when the scan runs relative to the create's save: a scan taken after
1045	     * the owner is persisted (as the {@link #householdSize(Owner) household size} derivation is)
1046	     * counts it among its household, while one taken before the save sees only the owners already
1047	     * present. Holding the household lookup in one place lets every household-derived value read the
1048	     * same set of members.
1049	     *
1050	     * @param owner the owner whose household members are wanted
1051	     * @return the owners sharing the owner's household, or an empty list when it has no household
1052	     */
1053	    private List<Owner> householdMembers(Owner owner) {
1054	        String household = owner.getHouseholdId();
1055	        if (household == null) {
1056	            return List.of();
1057	        }
1058	        return this.clinicService.findAllOwners().stream()
1059	            .filter(existing -> household.equals(existing.getHouseholdId()))
1060	            .toList();
1061	    }
1062	
1063	    private String householdId(Owner owner) {
1064	        String postcode = owner.getPostcode();
1065	        if (postcode == null || postcode.isBlank()) {
1066	            return null;
1067	        }
1068	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
1069	        return sha256Hasher.hexPrefix(key, HOUSEHOLD_ID_LENGTH);
1070	    }
1071	
1072	    /**
1073	     * Number of leading hex characters of the household hash retained as the shared
1074	     * {@code householdId}.
1075	     */
1076	    private static final int HOUSEHOLD_ID_LENGTH = 12;
1077	}
