242	    }
243	
244	    /**
245	     * Computes the owner's tenure as the number of elapsed fiscal years between the owner's
246	     * {@code registrationDate} and the current date: the fiscal year of "now" minus the fiscal year
247	     * of the registration date (see {@link #fiscalYearNumber(java.time.LocalDate)}). An owner
248	     * registered and read within the same fiscal year has a tenure of {@code 0}; each subsequent
249	     * fiscal year that has started adds one. Returns {@code 0} when no registration date is present,
250	     * so an owner without a registration date has no tenure.
251	     *
252	     * @param owner the owner being mapped
253	     * @return the owner's tenure in elapsed fiscal years, or {@code 0} when no registration date is present
254	     */
255	    default long tenureFiscalYears(Owner owner) {
256	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
257	        if (registrationDate == null) {
258	            return 0;
259	        }
260	        return (long) fiscalYearNumber(java.time.LocalDate.now()) - fiscalYearNumber(registrationDate);
261	    }
262	
263	    /**
264	     * Computes the calendar year that identifies the fiscal year containing {@code date}. The fiscal
265	     * year starts on 1 July and is labelled by the calendar year in which it starts, so a date on or
266	     * after 1 July belongs to that same year's fiscal year, while a date before 1 July belongs to the
267	     * previous year's fiscal year (e.g. {@code 2026-09-06} yields {@code 2026} and {@code 2026-06-15}
268	     * yields {@code 2025}).
269	     *
270	     * @param date the date whose fiscal year is wanted
271	     * @return the calendar year the fiscal year starts in
272	     */
273	    default int fiscalYearNumber(java.time.LocalDate date) {
274	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() : date.getYear() - 1;
275	    }
276	
277	    /**
278	     * Derives the owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}, where {@code YY} is the last
279	     * two digits of the fiscal year of the (business-day-adjusted) {@code registrationDate} (e.g.
280	     * {@code 'FY26'}). Returns {@code null} when no registration date is present.
281	     *
282	     * @param owner the owner being mapped
283	     * @return the formatted fiscal year, or {@code null} when no registration date is present
284	     */
285	    default String fiscalYear(Owner owner) {
286	        if (owner.getRegistrationDate() == null) {
287	            return null;
288	        }
289	        return String.format("FY%02d", fiscalYearNumber(owner.getRegistrationDate()) % 100);
290	    }
291	
292	    /**
293	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
294	     * where {@code YY} is the last two digits of the fiscal year of the (business-day-adjusted)
295	     * {@code registrationDate} (e.g. {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null} when either the
296	     * customer code or the registration date is absent.
297	     *
298	     * @param owner the owner being mapped
299	     * @return the formatted membership number, or {@code null} when it cannot be derived
300	     */
301	    default String membershipNumber(Owner owner) {
302	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
303	            return null;
304	        }
305	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYearNumber(owner.getRegistrationDate()) % 100);
306	    }
307	
308	    /**
309	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
310	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
311	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
312	     * the customer code is absent.
313	     *
314	     * @param owner the owner being mapped
315	     * @return the Luhn check digit, or {@code null} when no customer code is present
316	     */
317	    default Integer checkDigit(Owner owner) {
318	        String code = owner.getCustomerCode();
319	        if (code == null) {
320	            return null;
321	        }
322	        int sum = 0;
323	        boolean dbl = true;
324	        for (int i = code.length() - 1; i >= 0; i--) {
325	            char c = code.charAt(i);
326	            if (c < '0' || c > '9') {
327	                continue;
328	            }
329	            int d = c - '0';
330	            if (dbl) {
331	                d *= 2;
332	                if (d > 9) {
333	                    d -= 9;
334	                }
335	            }
336	            sum += d;
337	            dbl = !dbl;
338	        }
339	        return (10 - (sum % 10)) % 10;
340	    }
341	
342	    /**
343	     * Formats the owner's stored E.164 {@code telephone} for human display: the country calling
344	     * code, a space, then the national-significant digits grouped in threes separated by spaces
345	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw {@code telephone}
346	     * field keeps the unformatted E.164 value. The split between the country code and the national
347	     * digits mirrors the recognised calling codes of the {@code TelephoneNormalizer}: Australian
348	     * {@code +61} (9 national digits) and North American {@code +1} (10); an unrecognised or
349	     * malformed value falls back to a single leading digit. Returns the value unchanged when it is
350	     * {@code null}, blank, or not in E.164 form.
351	     *
352	     * @param owner the owner being mapped
353	     * @return the human-formatted telephone, or the raw value when it cannot be formatted
354	     */
355	    default String telephoneDisplay(Owner owner) {
356	        String telephone = owner.getTelephone();
357	        if (telephone == null || telephone.isBlank() || !telephone.startsWith("+")) {
358	            return telephone;
359	        }
360	        String digits = telephone.substring(1);
361	        int codeLength = (digits.startsWith("61") && digits.length() == 2 + 9) ? 2 : 1;
362	        String countryCode = digits.substring(0, codeLength);
363	        String national = digits.substring(codeLength);
364	        StringBuilder grouped = new StringBuilder();
365	        for (int i = 0; i < national.length(); i++) {
366	            if (i > 0 && i % 3 == 0) {
367	                grouped.append(' ');
368	            }
369	            grouped.append(national.charAt(i));
370	        }
371	        return "+" + countryCode + " " + grouped;
372	    }
373	
374	    Owner toOwner(OwnerDto ownerDto);
375	
376	    @Mapping(target = "id", ignore = true)
377	    @Mapping(target = "pets", ignore = true)
378	    Owner toOwner(OwnerFieldsDto ownerDto);
379	
380	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
381	
382	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
383	
384	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
385	        OwnerPageDto ownerPageDto = new OwnerPageDto();
386	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
387	        ownerPageDto.setPage(ownerPage.getNumber());
388	        ownerPageDto.setSize(ownerPage.getSize());
389	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
390	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
391	        return ownerPageDto;
392	    }
393	}
