16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	import java.util.Optional;
20	import java.util.function.Predicate;
21	
22	/**
23	 * The Australian region an owner's city belongs to. Each constant's name is the canonical region
24	 * code as stored and returned (e.g. {@code "NSW"}). Regions are resolved from a single fixed
25	 * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD});
26	 * a city that is not in the table has no known region.
27	 *
28	 * <p>This is the one place the city-to-region mapping lives, so every rule that keys off an owner's
29	 * region - such as the derived {@code locality} - resolves it identically.
30	 */
31	public enum Region {
32	
33	    NSW(2000, 2099, "Australia/Sydney"),
34	    VIC(3000, 3099, "Australia/Melbourne"),
35	    QLD(4000, 4099, "Australia/Brisbane");
36	
37	    private final int minPostcode;
38	
39	    private final int maxPostcode;
40	
41	    private final String timezone;
42	
43	    Region(int minPostcode, int maxPostcode, String timezone) {
44	        this.minPostcode = minPostcode;
45	        this.maxPostcode = maxPostcode;
46	        this.timezone = timezone;
47	    }
48	
49	    /**
50	     * Returns this region's IANA timezone name from the fixed region-to-timezone table
51	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
52	     * {@code QLD -> Australia/Brisbane}).
53	     *
54	     * @return the region's IANA timezone name
55	     */
56	    public String timezone() {
57	        return this.timezone;
58	    }
59	
60	    /**
61	     * Resolves the IANA timezone name for the given canonical region code from the fixed
62	     * region-to-timezone table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
63	     * {@code QLD -> Australia/Brisbane}). This is the one place the region-to-timezone mapping lives,
64	     * so every rule that labels an owner by timezone resolves it identically.
65	     *
66	     * @param code the canonical region code (e.g. {@code "NSW"}), or {@code null}
67	     * @return the matching IANA timezone name, or {@code null} when the code is {@code null} or has no
68	     *         known timezone (such as {@link #UNKNOWN_CODE})
69	     */
70	    public static String timezoneForCode(String code) {
71	        return forCode(code).map(Region::timezone).orElse(null);
72	    }
73	
74	    /** Fixed city -> region table; a city absent from this map has no known region. */
75	    private static final Map<String, Region> BY_CITY = Map.of(
76	        "Sydney", NSW,
77	        "Melbourne", VIC,
78	        "Brisbane", QLD);
79	
80	    /** Canonical region code returned when neither the postcode nor the city resolves to a region. */
81	    public static final String UNKNOWN_CODE = "UNKNOWN";
82	
83	    /**
84	     * Reports whether the given 4-digit postcode falls within this region's inclusive postcode range
85	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). This is the one place the region-to-postcode
86	     * range lives, so every rule that validates a postcode against an owner's region resolves it
87	     * identically.
88	     *
89	     * @param postcode the numeric value of the owner's 4-digit postcode
90	     * @return {@code true} when the postcode is within this region's range
91	     */
92	    public boolean acceptsPostcode(int postcode) {
93	        return postcode >= this.minPostcode && postcode <= this.maxPostcode;
94	    }
95	
96	    /**
97	     * Resolves the region named by the given canonical region code (e.g. {@code "NSW"}) by matching it
98	     * against the region constants' {@linkplain #name() names}. This is the by-code counterpart of
99	     * {@link #forCity(String)} and {@link #forPostcode(String)}, for a value that is already a region
100	     * code rather than a city or postcode, and is the one place a code is turned back into its
101	     * {@link Region}, so every rule that keys off a region code resolves it identically.
102	     *
103	     * @param code the canonical region code (e.g. {@code "NSW"}), or {@code null}
104	     * @return the matching region, or empty when the code is {@code null} or names no known region
105	     *         (such as {@link #UNKNOWN_CODE})
106	     */
107	    public static Optional<Region> forCode(String code) {
108	        if (code == null) {
109	            return Optional.empty();
110	        }
111	        return firstMatching(region -> region.name().equals(code));
112	    }
113	
114	    /**
115	     * Resolves the region for the given city from the fixed city-to-region table.
116	     *
117	     * @param city the owner's city, or {@code null}
118	     * @return the matching region, or empty when the city is {@code null} or has no known region
119	     */
120	    public static Optional<Region> forCity(String city) {
121	        return city == null ? Optional.empty() : Optional.ofNullable(BY_CITY.get(city));
122	    }
123	
124	    /**
125	     * Resolves the region whose postcode range contains the given 4-digit postcode
126	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
127	     *
128	     * @param postcode the owner's 4-digit postcode, or {@code null}
129	     * @return the matching region, or empty when the postcode is {@code null}, not numeric, or in no
130	     *         known range
131	     */
132	    public static Optional<Region> forPostcode(String postcode) {
133	        if (postcode == null) {
134	            return Optional.empty();
135	        }
136	        int value;
137	        try {
138	            value = Integer.parseInt(postcode.trim());
139	        } catch (NumberFormatException ex) {
140	            return Optional.empty();
141	        }
142	        return firstMatching(region -> region.acceptsPostcode(value));
143	    }
144	
145	    /**
146	     * Returns the first region constant matching the given predicate, or empty when none does. This is
147	     * the one place the "scan {@link #values()} for the first matching region" loop lives, so
148	     * {@link #forCode(String)} and {@link #forPostcode(String)} resolve a region identically, each
149	     * supplying only its own match condition.
150	     *
151	     * @param predicate the condition a region must satisfy to be selected
152	     * @return the first matching region, or empty when none matches
153	     */
154	    private static Optional<Region> firstMatching(Predicate<Region> predicate) {
155	        for (Region region : values()) {
156	            if (predicate.test(region)) {
157	                return Optional.of(region);
158	            }
159	        }
160	        return Optional.empty();
161	    }
162	
163	    /**
164	     * Resolves the canonical region code for an owner located at the given {@code postcode} and
165	     * {@code city}, preferring the postcode: it first looks up the region by
166	     * {@link #forPostcode(String) postcode range} (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and
167	     * only falls back to the {@link #forCity(String) city-to-region} table ({@code Sydney -> NSW},
168	     * {@code Melbourne -> VIC}, {@code Brisbane -> QLD}) when the postcode is absent or in no known
169	     * range. Returns the region's code, or {@link #UNKNOWN_CODE} when neither resolves.
170	     *
171	     * <p>This is the one place an owner's postcode and city are turned into a region code, so every
172	     * rule that labels an owner by region resolves it identically.
173	     *
174	     * @param postcode the owner's 4-digit postcode, or {@code null}
175	     * @param city the owner's city, or {@code null}
176	     * @return the canonical region code, or {@link #UNKNOWN_CODE} when neither postcode nor city resolves
177	     */
178	    public static String code(String postcode, String city) {
179	        return forPostcode(postcode)
180	            .or(() -> forCity(city))
181	            .map(Region::name)
182	            .orElse(UNKNOWN_CODE);
183	    }
184	}
